"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8118],{8472:e=>{e.exports=JSON.parse('{"functions":[{"name":"Initialize","desc":"Resets to a full paused `Counting`, registers the JoinSync sender, and wires\\nthe train-start, fuel-state, jump and game-over signals. Call exactly once\\nfrom the owning server script.","params":[],"returns":[],"function_type":"static","source":{"line":114,"path":"src/ServerStorage/SharedModules/ThreatTimerManager.luau"}}],"properties":[],"types":[],"name":"ThreatTimerManager","desc":"Server-authoritative countdown to the Leviathan\'s arrival. Like\\n`TrainFuelManager` it has no per-frame loop: each state change snapshots\\n`remaining` under the old speed, picks the new speed, schedules the next\\nphase advance with `task.delay` (guarded by a nonce), and broadcasts\\n`ThreatStateSync`.\\n\\nPhases: `Counting` (`ARRIVAL_SECONDS`; 1\xd7, or `STALLED_SPEED` while the\\ntrain is stalled) \u2192 `Imminent` (`SPAWN_DELAY` real seconds) \u2192 `Arrived`\\n(`Signals.OnThreatArrived` fires once). Paused before the first un-brake,\\nduring a jump, and after game over. Every jump arrival resets to a full\\n`Counting`.","realm":["Server"],"source":{"line":19,"path":"src/ServerStorage/SharedModules/ThreatTimerManager.luau"}}')}}]);